import { defineConfig, globalIgnores } from "eslint/config";
import nextCoreWebVitals from "eslint-config-next/core-web-vitals";

export default defineConfig([
  // Keep the starter on the flat config export that actually runs under the pinned ESLint/Next toolchain.
  ...nextCoreWebVitals,
  // `dist/**` is generated by `npm run prepare:portable`: it contains a verbatim
  // copy of the standalone build, its bundled node_modules and the launchers.
  // Linting generated output only produces noise from code this repository does
  // not own, so it is ignored the same way the other build directories are.
  globalIgnores([".next/**", "out/**", "build/**", "dist/**", "next-env.d.ts"]),
]);
